const body = document.body;
const modeButtons = [...document.querySelectorAll("[data-mode]")];
const views = [...document.querySelectorAll("[data-view]")];
const langButton = document.querySelector(".language-switch");
const params = new URLSearchParams(location.search);
const storedLanguage = localStorage.getItem("portfolio-language");
let language = params.get("lang") || storedLanguage || (navigator.language.toLowerCase().startsWith("tr") ? "tr" : "en");
let mode = params.get("view") === "silveroak" ? "silveroak" : "personal";

function setLanguage(nextLanguage, updateUrl = true) {
  language = nextLanguage === "en" ? "en" : "tr";
  document.documentElement.lang = language;
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const translated = copy[language][element.dataset.i18n];
    if (translated) element.innerHTML = translated;
  });
  document.querySelector(".lang-current").textContent = language.toUpperCase();
  document.querySelector(".lang-next").textContent = language === "tr" ? "EN" : "TR";
  localStorage.setItem("portfolio-language", language);
  document.title = mode === "silveroak"
    ? `SilverOak Tech — ${language === "tr" ? "Oyunlar ve Mobil Ürünler" : "Games & Mobile Products"}`
    : `Cenk Gürses — Team Lead & Senior Software Engineer`;
  if (updateUrl) syncUrl();
}

function setMode(nextMode, shouldScroll = true) {
  mode = nextMode === "silveroak" ? "silveroak" : "personal";
  body.classList.toggle("mode-silveroak", mode === "silveroak");
  body.classList.toggle("mode-personal", mode === "personal");
  modeButtons.forEach((button) => {
    const active = button.dataset.mode === mode;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  views.forEach((view) => { view.hidden = view.dataset.view !== mode; });
  document.querySelector(".mini-brand-mark").textContent = mode === "personal" ? "CG" : "SO";
  if (shouldScroll) window.scrollTo({ top: 0, behavior: "smooth" });
  setLanguage(language, false);
  syncUrl();
  requestAnimationFrame(observeReveals);
}

function syncUrl() {
  const next = new URL(location.href);
  if (mode === "silveroak") next.searchParams.set("view", "silveroak"); else next.searchParams.delete("view");
  if (language === "en") next.searchParams.set("lang", "en"); else next.searchParams.delete("lang");
  history.replaceState({}, "", `${next.pathname}${next.search}${next.hash}`);
}

modeButtons.forEach((button) => button.addEventListener("click", () => setMode(button.dataset.mode)));
document.querySelectorAll("[data-switch-link]").forEach((control) => control.addEventListener("click", (event) => {
  event.preventDefault(); setMode(control.dataset.switchLink);
}));
langButton.addEventListener("click", () => setLanguage(language === "tr" ? "en" : "tr"));
window.addEventListener("scroll", () => document.querySelector(".site-header").classList.toggle("is-scrolled", scrollY > 12), { passive: true });

let observer;
function observeReveals() {
  if (observer) observer.disconnect();
  observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => { if (entry.isIntersecting) entry.target.classList.add("is-visible"); });
  }, { threshold: .12 });
  document.querySelectorAll("[data-view]:not([hidden]) .reveal").forEach((element, index) => {
    element.style.transitionDelay = `${Math.min(index % 4, 3) * 45}ms`;
    observer.observe(element);
  });
}

setLanguage(language, false);
setMode(mode, false);
